const WERKZEUG = 'tasks_internal.create_task';
const ADAPTER_ID = 'tasks_internal';
const ULID = '[0-9A-HJKMNP-TV-Z]{26}';
const alle = $input.all();
if (alle.length !== 1) {
  throw new Error('adp_tasks_internal_invalid_input: genau ein Aufruf je Ausfuehrung erwartet, erhalten ' + alle.length);
}
const e = alle[0].json;
const p = (e.payload && typeof e.payload === 'object' && !Array.isArray(e.payload)) ? e.payload : null;
const fehler = [];
const txt = function (v, min, max) { return typeof v === 'string' && v.length >= min && v.length <= max; };
const zeit = function (v) { return typeof v === 'string' && /Z$/.test(v) && !isNaN(Date.parse(v)); };
const norm = function (v) { return (v === undefined || v === null || v === '') ? null : new Date(v).toISOString().replace(/[.][0-9]{3}Z$/, 'Z'); };
const oder = function (v) { return (v === undefined || v === '') ? null : v; };
const obj = function (v) { return v && typeof v === 'object' && !Array.isArray(v); };
if (!/^[a-z][a-z0-9_]{2,63}$/.test(String(e.context_id || ''))) fehler.push('context_id fehlt oder hat kein gueltiges Format');
if (e.tool_id !== WERKZEUG) fehler.push('tool_id passt nicht zu diesem Adapter');
if (!/^act_[A-Za-z0-9_]{6,64}$/.test(String(e.action_id || ''))) fehler.push('action_id fehlt oder ist ungueltig');
if (!p) {
  fehler.push('payload fehlt');
} else {
  if (p.context_id !== e.context_id) fehler.push('context_mismatch: payload.context_id weicht vom Aufrufkontext ab');
  if (!/^[0-9]+[.][0-9]+[.][0-9]+$/.test(String(p.schema_version || ''))) fehler.push('schema_version ungueltig');
  if (!zeit(p.created_at)) fehler.push('created_at fehlt oder ist kein UTC-Zeitstempel');
  if (!(obj(p.producer) && p.producer.producer_type && p.producer.producer_id)) fehler.push('producer unvollstaendig');
  if (!new RegExp('^tsk_' + ULID + '$').test(String(p.task_id || ''))) fehler.push('task_id ungueltig');
  if (!txt(p.title, 3, 200)) fehler.push('title fehlt oder Laenge unzulaessig');
  if (!txt(p.success_criterion, 3, 1000)) fehler.push('success_criterion fehlt oder Laenge unzulaessig');
  if (['jarvis', 'rolf', 'mitarbeiter', 'externer'].indexOf(p.actor) === -1) fehler.push('actor unzulaessig');
  if (p.actor && p.actor !== 'jarvis' && !obj(p.assignee)) fehler.push('assignee fehlt fuer menschlichen Verantwortlichen');
  if (['open', 'in_progress', 'blocked', 'waiting_external', 'done', 'cancelled', 'superseded'].indexOf(p.status) === -1) fehler.push('status unzulaessig');
  if (p.status === 'done' && (!zeit(p.closed_at) || !Array.isArray(p.closing_evidence_ids) || p.closing_evidence_ids.length === 0)) fehler.push('done verlangt closed_at und closing_evidence_ids');
  if (['low', 'normal', 'high', 'critical'].indexOf(p.priority) === -1) fehler.push('priority unzulaessig');
  if (!/^[a-f0-9]{64}$/.test(String(p.idempotency_key || ''))) fehler.push('idempotency_key ist kein SHA-256');
  if (!obj(p.origin)) fehler.push('origin fehlt');
  if (p.due_at !== undefined && p.due_at !== null && !zeit(p.due_at)) fehler.push('due_at ist kein UTC-Zeitstempel');
}
let zeile = null;
let erwartet = null;
if (fehler.length === 0) {
  zeile = { task_id: p.task_id, schema_version: p.schema_version, context_id: p.context_id, title: p.title, success_criterion: p.success_criterion, actor: p.actor, status: p.status, priority: p.priority, due_at: oder(p.due_at), idempotency_key: p.idempotency_key, body: p };
  erwartet = { context_id: p.context_id, title: p.title, success_criterion: p.success_criterion, actor: p.actor, status: p.status, priority: p.priority, due_at: norm(p.due_at), idempotency_key: p.idempotency_key };
}
const basis = { adapter_id: ADAPTER_ID, tool_id: WERKZEUG, context_id: e.context_id || null, action_id: e.action_id || null, trace_id: e.trace_id || null };
if (fehler.length > 0) {
  return [{ json: Object.assign({ route: 'invalid', fehler: fehler }, basis) }];
}
return [{ json: Object.assign({ route: e.dry_run === true ? 'dry_run' : e.context_id, requested_id: p.task_id, zeile_b64: Buffer.from(JSON.stringify(zeile), 'utf8').toString('base64'), expected: erwartet }, basis) }];

const e = $('Eingabe pruefen').first().json;
const r = $input.first().json;
const basis = { adapter_id: e.adapter_id, tool_id: e.tool_id, context_id: e.context_id, action_id: e.action_id, trace_id: e.trace_id };
if (r.found !== true) {
  return [{ json: Object.assign({ status: 'error', write_outcome: r.write_outcome || 'unknown', error: { error_class: 'consistency', error_code: 'readback_missing', retryable: false, message: 'Zielobjekt nach dem Schreiben nicht lesbar' } }, basis) }];
}
const beobachtet = { context_id: r.context_id, title: r.title, success_criterion: r.success_criterion, actor: r.actor, status: r.status, priority: r.priority, due_at: r.due_at || null, idempotency_key: r.idempotency_key };
return [{ json: Object.assign({ status: 'ok', write_outcome: r.write_outcome, target_object_ref: { object_type: 'task', object_id: r.task_id, requested_id: e.requested_id }, verification_method: 'readback', observed: beobachtet, expected: e.expected }, basis) }];

const e = $input.first().json;
// TS-10: Ohne Fehlerliste kommt der Eintrag aus dem Ausweichausgang der Kontextweiche.
const fehler = (Array.isArray(e.fehler) && e.fehler.length > 0) ? e.fehler : ['context_id ohne Kontextweiche'];
return [{ json: { status: 'error', adapter_id: e.adapter_id, tool_id: e.tool_id, context_id: e.context_id, action_id: e.action_id, write_outcome: 'none', error: { error_class: 'validation', error_code: 'invalid_input', retryable: false, message: fehler.join('; ') }, trace_id: e.trace_id } }];

const e = $('Eingabe pruefen').first().json;
const f = $input.first().json;
const roh = JSON.stringify(f.error || f).slice(0, 2000);
let klasse = 'unknown';
let code = 'db_error';
let wiederholbar = false;
if (/42501|permission denied/i.test(roh)) { klasse = 'permission'; code = 'permission_denied'; }
else if (/23505|duplicate key/i.test(roh)) { klasse = 'conflict'; code = 'unique_violation'; }
else if (/23514|check constraint/i.test(roh)) { klasse = 'validation'; code = 'constraint_violation'; }
else if (/23503|foreign key/i.test(roh)) { klasse = 'validation'; code = 'reference_missing'; }
else if (/timeout|timed out|ETIMEDOUT/i.test(roh)) { klasse = 'timeout'; code = 'db_timeout'; wiederholbar = true; }
else if (/ECONNREFUSED|ECONNRESET|ENOTFOUND|terminat|connection/i.test(roh)) { klasse = 'transient_network'; code = 'db_unreachable'; wiederholbar = true; }
return [{ json: { status: 'error', adapter_id: e.adapter_id, tool_id: e.tool_id, context_id: e.context_id, action_id: e.action_id, write_outcome: 'unknown', error: { error_class: klasse, error_code: code, retryable: wiederholbar, message: roh.slice(0, 500) }, trace_id: e.trace_id } }];
